export const QuantityStepper = ({ value, onChange, max = 99 }) => <div className="flex items-center gap-1 rounded-xl border bg-[var(--surface)] p-1">
    <button
  type="button"
  onClick={() => onChange(value - 1)}
  className="flex h-7 w-7 items-center justify-center rounded-lg text-[var(--muted)] transition hover:bg-[var(--surface-2)] hover:text-brand-600"
  aria-label="minus"
>
      <Minus size={14} />
    </button>
    <span className="w-7 text-center text-xs font-extrabold">{value}</span>
    <button
  type="button"
  onClick={() => onChange(Math.min(max, value + 1))}
  className="flex h-7 w-7 items-center justify-center rounded-lg text-[var(--muted)] transition hover:bg-[var(--surface-2)] hover:text-brand-600"
  aria-label="plus"
>
      <Plus size={14} />
    </button>
  </div>;
export const ProductCard = ({ product, compact = false }) => {
  const { t } = useTranslation();
  const { addToCart, toggleFavorite, favorites } = useShop();
  const isFav = favorites.includes(product.id);
  const off = discountPercent(product);
  return <div className="group card relative flex flex-col overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-soft">
      <Link to={`/product/${product.id}`} className="relative block">
        <div className={cn("relative flex items-center justify-center overflow-hidden bg-gradient-to-br", product.gradient, compact ? "h-36" : "h-44")}>
          {product.img ? (
            <img alt={product.name} className="h-full w-full object-contain p-3 transition-transform duration-500 group-hover:scale-110" src={product.img} />
          ) : (
            <span className={cn("transition-transform duration-500 group-hover:scale-110", compact ? "text-5xl" : "text-6xl")}>{product.emoji}</span>
          )}
          <div className="absolute inset-x-0 bottom-0 h-10 bg-gradient-to-t from-black/5 to-transparent" />
          {off > 0 && <span className="absolute left-3 top-3 rounded-lg bg-rose-500 px-2 py-1 text-[10px] font-black text-white shadow-lg shadow-rose-500/30">
              -{off}%
            </span>}
          {product.popular && off === 0 && <span className="absolute left-3 top-3 rounded-lg bg-brand-600 px-2 py-1 text-[9px] font-black uppercase tracking-wide text-white">
              {t("popular")}
            </span>}
          <span className="absolute bottom-3 left-3 flex items-center gap-1 rounded-lg bg-white/80 px-1.5 py-0.5 text-[10px] font-extrabold text-gray-900 backdrop-blur">
            <Star size={10} className="fill-amber-400 text-amber-400" /> {product.rating}
          </span>
        </div>
      </Link>

      <button
    onClick={() => toggleFavorite(product.id)}
    className={cn(
      "absolute right-3 top-3 flex h-8 w-8 items-center justify-center rounded-full border border-white/50 bg-white/80 text-gray-500 shadow-sm backdrop-blur transition hover:scale-105",
      isFav && "text-rose-500"
    )}
    aria-label="favorite"
  >
        <Heart size={15} className={isFav ? "fill-rose-500" : ""} />
      </button>

      <div className="flex flex-1 flex-col p-3.5">
        <p className="text-[10px] font-bold uppercase tracking-wide text-[var(--muted)]">{product.unit}</p>
        <Link to={`/product/${product.id}`} className="mt-0.5 line-clamp-2 text-sm font-extrabold leading-snug transition hover:text-brand-600">
          {product.name}
        </Link>
        <div className="mt-auto flex items-end justify-between gap-2 pt-3">
          <div>
            {product.oldPrice && <p className="text-[10px] font-bold text-[var(--muted)] line-through">{formatUZS(product.oldPrice)}</p>}
            <p className="font-display text-sm font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(product.price)}</p>
          </div>
          <button
    onClick={() => addToCart(product.id)}
    className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-600 text-white shadow-lg shadow-brand-600/25 transition hover:bg-brand-700 active:scale-95"
    aria-label={t("addToCart")}
  >
            <Plus size={17} strokeWidth={3} />
          </button>
        </div>
      </div>
    </div>;
};
export const EmptyState = ({
  icon,
  title,
  description,
  action
}) => <div className="flex flex-col items-center justify-center rounded-3xl border border-dashed px-6 py-16 text-center" style={{ borderColor: "var(--border)" }}>
    <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-brand-500/10 text-brand-600 dark:text-brand-400">
      {icon ?? <PackageOpen size={28} />}
    </div>
    <h3 className="font-display text-lg font-extrabold">{title}</h3>
    {description && <p className="mt-1 max-w-sm text-sm text-[var(--muted)]">{description}</p>}
    {action && <div className="mt-5">{action}</div>}
  </div>;
export const Modal = ({ open, onClose, title, children, size = "md" }) => {
  useEffect(() => {
    if (open) document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);
  if (!open) return null;
  const widths = { sm: "max-w-md", md: "max-w-xl", lg: "max-w-3xl" };
  return <div className="fixed inset-0 z-[80] flex items-end justify-center p-0 sm:items-center sm:p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className={cn("relative z-10 max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-[var(--surface)] p-5 shadow-2xl animate-fade-up sm:rounded-3xl sm:p-6", widths[size])}>
        <div className="mb-4 flex items-center justify-between">
          {title && <h3 className="font-display text-lg font-extrabold">{title}</h3>}
          <button onClick={onClose} className="icon-btn ml-auto h-9 w-9"><X size={16} /></button>
        </div>
        {children}
      </div>
    </div>;
};
const statusStyles = {
  confirmed: "bg-sky-500/15 text-sky-700 dark:text-sky-300",
  preparing: "bg-amber-500/15 text-amber-700 dark:text-amber-300",
  delivering: "bg-brand-500/15 text-brand-700 dark:text-brand-300",
  delivered: "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300",
  cancelled: "bg-rose-500/15 text-rose-700 dark:text-rose-300"
};
const statusKeys = {
  confirmed: "statusConfirmed",
  preparing: "statusPreparing",
  delivering: "statusDelivering",
  delivered: "statusDelivered",
  cancelled: "statusCancelled"
};
export const OrderStatusBadge = ({ status }) => {
  const { t } = useTranslation();
  return <span className={cn("badge", statusStyles[status])}>{t(statusKeys[status])}</span>;
};
export const OrderProgress = ({ status }) => {
  const { t } = useTranslation();
  const steps = [
    { key: "confirmed", label: "stepConfirmed" },
    { key: "preparing", label: "stepPreparing" },
    { key: "delivering", label: "stepDelivering" },
    { key: "delivered", label: "stepDelivered" }
  ];
  const activeIndex = status === "cancelled" ? -1 : steps.findIndex((s) => s.key === status);
  if (status === "cancelled") {
    return <div className="rounded-xl bg-rose-500/10 px-3 py-2 text-xs font-extrabold text-rose-600 dark:text-rose-400">{t("statusCancelled")}</div>;
  }
  return <div className="flex items-center">
      {steps.map((step, i) => {
    const done = i <= activeIndex;
    return <React.Fragment key={step.key}>
            <div className="flex flex-col items-center gap-1">
              <span className={cn("flex h-7 w-7 items-center justify-center rounded-full text-[10px] font-black transition", done ? "bg-brand-600 text-white" : "bg-[var(--surface-3)] text-[var(--muted)]")}>
                {done ? <Check size={13} strokeWidth={3} /> : i + 1}
              </span>
              <span className={cn("whitespace-nowrap text-[9px] font-bold", done ? "text-brand-600 dark:text-brand-400" : "text-[var(--muted)]")}>{t(step.label)}</span>
            </div>
            {i < steps.length - 1 && <span className={cn("mx-1 mb-4 h-0.5 flex-1 rounded-full", i < activeIndex ? "bg-brand-500" : "bg-[var(--surface-3)]")} />}
          </React.Fragment>;
  })}
    </div>;
};
export const Toaster = () => {
  const { toasts, dismissToast } = useShop();
  return <div className="pointer-events-none fixed inset-x-0 top-4 z-[100] flex flex-col items-center gap-2 px-4 sm:left-auto sm:right-4 sm:items-end">
      {toasts.map((toast) => <div
    key={toast.id}
    className={cn(
      "pointer-events-auto flex w-full max-w-sm items-center gap-2.5 rounded-2xl border bg-[var(--surface)] px-4 py-3 shadow-2xl animate-slide-in-right",
      toast.type === "error" ? "border-rose-400/40" : toast.type === "info" ? "border-sky-400/40" : "border-brand-400/40"
    )}
  >
          <span
    className={cn(
      "flex h-7 w-7 shrink-0 items-center justify-center rounded-full",
      toast.type === "error" ? "bg-rose-500/15 text-rose-600" : toast.type === "info" ? "bg-sky-500/15 text-sky-600" : "bg-brand-500/15 text-brand-600"
    )}
  >
            {toast.type === "info" ? "i" : <Check size={14} strokeWidth={3} />}
          </span>
          <p className="flex-1 text-xs font-bold">{toast.message}</p>
          <button onClick={() => dismissToast(toast.id)} className="text-[var(--muted)] hover:text-[var(--text)]"><X size={14} /></button>
        </div>)}
    </div>;
};
